seq=''.join(l.strip() for l in open('region.fasta') if not l.startswith('>'))
n=len(seq)
k=12
from collections import defaultdict
d=defaultdict(list)
for i in range(n-k+1): d[seq[i:i+k]].append(i)
# collect matching pairs off main diagonal, cluster into diagonal runs
pairs=[]
for kk,v in d.items():
    if len(v)>1:
        for a in range(len(v)):
            for b in range(a+1,len(v)):
                i,j=v[a],v[b]
                if j-i>k: pairs.append((i,j))
print('npairs',len(pairs))
# cluster: sort by i, then group by gap j-i approximate contiguous
pairs.sort()
# find runs where (i+1,j+1) also present
pset=set(pairs)
runs=[]
used=set()
for (i,j) in pairs:
    if (i,j) in used: continue
    if (i-1,j-1) in pset: continue
    ii,jj=i,j
    while (ii+1,jj+1) in pset:
        ii+=1; jj+=1
    runs.append((i,j,ii,jj,ii-i+k))
runs.sort(key=lambda r:-r[4])
for r in runs[:15]:
    print('match A %d-%d with B %d-%d  len=%d'%(r[0]+1,r[2]+k,r[1]+1,r[3]+k,r[4]))
