def stopcount(s,w=300):
    out=[]
    for i in range(0,len(s)-w+1,w):
        win=s[i:i+w]
        out.append([sum(1 for j in range(f,len(win)-2,3) if win[j:j+3] in stops) for f in range(3)])
    return out
print('PLUS strand stop codons per 300bp window (frames 0,1,2):')
for idx,v in enumerate(stopcount(seq)): print(idx*300+1, v)
print()
print('MINUS strand (coordinates shown as forward-ranges):')
for idx,v in enumerate(stopcount(rc)): print(idx*300+1, v)
