def allorfs(s,label):
    res=[]
    for f in range(3):
        start=None
        for j in range(f,len(s)-2,3):
            cod=s[j:j+3]
            if cod in ('ATG','GTG','TTG') and start is None: start=j
            elif cod in stops and start is not None:
                if j+3-start>=150: res.append((start,j+3,label,f))
                start=None
        if start is not None and len(s)-start>=150: res.append((start,len(s),label,f))
    return res
